//! Claims, leases, overlap detection, scope, and live coverage declarations.

use super::*;

mod scope;

use scope::{compile_scope_glob, normalize_paths, normalize_scope_values, normalize_symbols};
pub(super) use scope::{intersect_paths, task_scope_on};

impl LodestarStore {
    /// Claim a task: the coordination primitive. A guarded compare-and-swap —
    /// succeeds only if the task is open, its lease has expired, the caller
    /// already owns it, or it is a parked task whose parking grace has elapsed
    /// (ADR-0020: a vanished owner cannot strand it forever). Returns true iff
    /// this caller won the claim.
    pub fn claim_task(&self, id: &str, agent: &str, lease_secs: i64, now: i64) -> Result<bool> {
        self.claim_task_with_scope(id, agent, lease_secs, &TaskScope::default(), now)
    }

    /// Claim a task and replace its advisory scope in one transaction
    /// (ADR-0024). A losing claimant never writes scope. Existing callers use
    /// [`claim_task`](Self::claim_task) and therefore declare no scope.
    pub fn claim_task_with_scope(
        &self,
        id: &str,
        agent: &str,
        lease_secs: i64,
        scope: &TaskScope,
        now: i64,
    ) -> Result<bool> {
        self.claim_task_with_partial_scope(
            id,
            agent,
            lease_secs,
            Some(&scope.paths),
            Some(&scope.symbols),
            now,
        )
    }

    /// Claim work while replacing only the scope fields the caller supplied.
    /// Omitted fields retain their prior rows inside the same claim transaction.
    pub(crate) fn claim_task_with_partial_scope(
        &self,
        id: &str,
        agent: &str,
        lease_secs: i64,
        paths: Option<&[String]>,
        symbols: Option<&[String]>,
        now: i64,
    ) -> Result<bool> {
        let paths = paths.map(normalize_paths).transpose()?;
        let symbols = symbols.map(normalize_symbols);
        let transaction = Transaction::new_unchecked(&self.conn, TransactionBehavior::Immediate)?;
        let parked_cutoff = now - PARKING_GRACE_SECS;
        refuse_beyond_claim_limit(&transaction, id, agent)?;
        // The evidence window survives a lapse (ADR-0048). Re-claiming used to
        // reset `claim_started_at` to now, which silently put every commit made
        // before the lapse outside the window the agent could prove. That did
        // not merely under-report: because the verdict is computed over the
        // nodes the evidence covers, a lapse let an agent submit the surviving
        // sliver and collect an `aligned` receipt while the bulk of the change
        // went unchecked. So a re-claim by the same owner keeps the window open;
        // the hole it leaves is recorded in the task log and read back by
        // `claim_window` (ADR-0064 d5), and conformance refuses to certify a
        // discontinuous window on its own authority.
        let changed = transaction.execute(
            "UPDATE tasks
                SET status = 'claimed', owner = ?2,
                    claim_started_at = CASE
                        WHEN status = 'claimed' AND owner = ?2
                        THEN claim_started_at ELSE ?4 END,
                    -- The branch belongs to the evidence window, so it follows
                    -- the same rule as `claim_started_at`: a same-owner
                    -- re-claim keeps it, a different owner opens a fresh
                    -- window and re-reads it. Recording the *current* branch
                    -- on every re-claim would let an agent that moved on
                    -- silently rename the branch its earlier commits were made
                    -- on, which is the one thing this column exists to pin.
                    --
                    -- Joined from what the session already told `open_session`
                    -- (ADR-0057): nobody declares anything new, and a session
                    -- that declared no branch records NULL rather than a guess,
                    -- because the server never inspects Git (ADR-0044).
                    branch = CASE
                        WHEN status = 'claimed' AND owner = ?2 THEN branch
                        ELSE (SELECT branch FROM session_context
                               WHERE agent_id = ?2) END,
                    lease_expires_at = ?3, parked_at = NULL, updated_at = ?4
              WHERE id = ?1
                                AND blocked_by IS NULL
                                AND NOT (
                                        owner IS NOT NULL
                                        AND owner NOT LIKE 'session:v1:%'
                                        AND ?2 LIKE 'session:v1:%'
                                )
                AND (status = 'open'
                     OR (status = 'claimed' AND lease_expires_at < ?4)
                     OR (status = 'claimed' AND owner = ?2)
                     OR (status IN ('needs_input', 'paused')
                         AND parked_at IS NOT NULL AND parked_at < ?5))",
            params![id, agent, now + lease_secs, now, parked_cutoff],
        )?;
        if changed == 1 {
            if let Some(paths) = &paths {
                transaction.execute(
                    "DELETE FROM task_scopes WHERE task_id = ?1 AND kind = 'path'",
                    params![id],
                )?;
                for path in paths {
                    transaction.execute(
                        "INSERT INTO task_scopes (task_id, kind, value) VALUES (?1, 'path', ?2)",
                        params![id, path],
                    )?;
                }
            }
            if let Some(symbols) = &symbols {
                transaction.execute(
                    "DELETE FROM task_scopes WHERE task_id = ?1 AND kind = 'symbol'",
                    params![id],
                )?;
                for symbol in symbols {
                    transaction.execute(
                        "INSERT INTO task_scopes (task_id, kind, value) VALUES (?1, 'symbol', ?2)",
                        params![id, symbol],
                    )?;
                }
            }
            events::record(
                &transaction,
                id,
                TaskEventKind::Claimed,
                Some(agent),
                now,
                &format!(r#"{{"lease_secs":{lease_secs}}}"#),
            )?;
        }
        transaction.commit()?;
        Ok(changed == 1)
    }

    /// Active claims whose declared scope intersects a requested pre-flight
    /// scope. Advisory only: no state is changed and no lock is granted.
    ///
    /// `requester` is the asking agent id, used only to read the branch that
    /// agent already declared at `open_session`. The branch is never taken as a
    /// call argument: it is declared once per session (ADR-0035 decision 2), and
    /// a second place to state it would let a caller check against a branch it
    /// is not on, with nothing able to tell which one was true.
    pub fn check_claim_overlap(
        &self,
        requested: &TaskScope,
        exclude_task_id: Option<&str>,
        requester: Option<&str>,
        now: i64,
    ) -> Result<ClaimOverlapReport> {
        let requested = normalize_scope_values(requested);
        let requester_branch = self.declared_branch(requester)?;
        let mut statement = self.conn.prepare(
            "SELECT id, owner, lease_expires_at
             FROM tasks
             WHERE status = 'claimed' AND lease_expires_at >= ?1
               AND (?2 IS NULL OR id != ?2)
             ORDER BY created_at ASC, id ASC",
        )?;
        let claims = statement.query_map(params![now, exclude_task_id], |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, String>(1)?,
                row.get::<_, i64>(2)?,
            ))
        })?;
        let mut overlaps = Vec::new();
        for claim in claims {
            let (task_id, owner, lease_expires_at) = claim?;
            let scope = task_scope_on(&self.conn, &task_id)?;
            let matching_paths = intersect_paths(&requested.paths, &scope.paths)?;
            let matching_symbols = requested
                .symbols
                .iter()
                .filter(|symbol| scope.symbols.contains(symbol))
                .cloned()
                .collect::<Vec<_>>();
            if !matching_paths.is_empty() || !matching_symbols.is_empty() {
                let owner_branch = self.declared_branch(Some(&owner))?;
                let signal =
                    OverlapSignal::classify(requester_branch.as_deref(), owner_branch.as_deref());
                overlaps.push(ClaimOverlap {
                    task_id,
                    owner,
                    lease_expires_at,
                    scope,
                    matching_paths,
                    matching_symbols,
                    owner_branch,
                    signal,
                });
            }
        }
        Ok(ClaimOverlapReport {
            requester_branch,
            claims: overlaps,
        })
    }

    /// The branch an agent declared, treating an unregistered agent and a blank
    /// declaration alike: both are "said nothing", not "said empty".
    fn declared_branch(&self, agent: Option<&str>) -> Result<Option<String>> {
        let Some(agent) = agent.map(str::trim).filter(|agent| !agent.is_empty()) else {
            return Ok(None);
        };
        Ok(self
            .session_context(agent)?
            .and_then(|(context, _)| context.branch)
            .map(|branch| branch.trim().to_string())
            .filter(|branch| !branch.is_empty()))
    }

    /// Read one task's declared advisory scope.
    pub fn task_scope(&self, task_id: &str) -> Result<TaskScope> {
        if self.get_task(task_id)?.is_none() {
            return Err(LodestarError::NotFound(task_id.to_string()));
        }
        task_scope_on(&self.conn, task_id)
    }

    /// Active policy nodes covered by a task's declared advisory scope.
    pub(crate) fn governed_nodes_for_task_scope(&self, task_id: &str) -> Result<Vec<String>> {
        let scope = self.task_scope(task_id)?;
        let matchers = scope
            .paths
            .iter()
            .map(|path| compile_scope_glob(path))
            .collect::<Result<Vec<_>>>()?;
        let mut nodes = Vec::new();
        for node in self.governed_node_ids()? {
            let path_matches = node
                .strip_prefix("artifact:")
                .is_some_and(|path| matchers.iter().any(|matcher| matcher.is_match(path)));
            if path_matches || scope.symbols.contains(&node) {
                nodes.push(node);
            }
        }
        nodes.sort();
        nodes.dedup();
        Ok(nodes)
    }

    /// Extend a still-live lease on a task the caller owns (heartbeat). Once a
    /// lease lapses it cannot be renewed: the owner must re-claim, which keeps
    /// the evidence window open but records the lapse (ADR-0048).
    pub fn renew_lease(&self, id: &str, agent: &str, lease_secs: i64, now: i64) -> Result<bool> {
        let transaction = Transaction::new_unchecked(&self.conn, TransactionBehavior::Immediate)?;
        let changed = transaction.execute(
            "UPDATE tasks SET lease_expires_at = ?3, updated_at = ?4
                            WHERE id = ?1 AND owner = ?2 AND status = 'claimed'
                                AND lease_expires_at >= ?4 AND blocked_by IS NULL",
            params![id, agent, now + lease_secs, now],
        )?;
        if changed == 1 {
            events::record(
                &transaction,
                id,
                TaskEventKind::LeaseRenewed,
                Some(agent),
                now,
                &format!(r#"{{"lease_secs":{lease_secs},"heartbeat":false}}"#),
            )?;
        }
        transaction.commit()?;
        Ok(changed == 1)
    }

    /// Renew a lease because the owner is demonstrably still working (ADR-0052).
    ///
    /// A lease is a heartbeat, not a deadline, and an agent doing its job should
    /// not lose its claim to a long `cargo test`. Any authenticated call naming
    /// the task is proof of life, so renewal rides on calls already being made
    /// rather than on the owner remembering `renew_lease` — the same shape that
    /// made question delivery adopted in ADR-0046, because a capability that
    /// depends on remembering is adopted at a rate of zero.
    ///
    /// `MAX` so a heartbeat can only ever extend a lease, never shorten one an
    /// owner deliberately took long. `claim_started_at` is untouched, so the
    /// evidence window still bounds exactly what the claim covered (ADR-0048 is
    /// unaffected). Owner-only and silent: a call from a non-owner, or against
    /// an already-lapsed lease, renews nothing and does not error, because the
    /// call has its own job to do and a lapse must still require a deliberate
    /// re-claim rather than being resurrected by a passing read.
    pub fn touch_lease(&self, id: &str, agent: &str, lease_secs: i64, now: i64) -> Result<bool> {
        let transaction = Transaction::new_unchecked(&self.conn, TransactionBehavior::Immediate)?;
        let changed = transaction.execute(
            "UPDATE tasks SET lease_expires_at = MAX(lease_expires_at, ?3), updated_at = ?4
                            WHERE id = ?1 AND owner = ?2 AND status = 'claimed'
                                AND lease_expires_at >= ?4 AND blocked_by IS NULL",
            params![id, agent, now + lease_secs, now],
        )?;
        if changed == 1 {
            events::record(
                &transaction,
                id,
                TaskEventKind::LeaseRenewed,
                Some(agent),
                now,
                &format!(r#"{{"lease_secs":{lease_secs},"heartbeat":true}}"#),
            )?;
        }
        transaction.commit()?;
        Ok(changed == 1)
    }

    /// Release a claim back to `open` (owner-guarded).
    pub fn release_task(&self, id: &str, agent: &str, now: i64) -> Result<bool> {
        let transaction = Transaction::new_unchecked(&self.conn, TransactionBehavior::Immediate)?;
        let changed = transaction.execute(
            "UPDATE tasks SET status = 'open', owner = NULL, claim_started_at = NULL,
                                                            lease_expires_at = NULL, updated_at = ?3
                            WHERE id = ?1 AND owner = ?2 AND status = 'claimed'
                                AND blocked_by IS NULL",
            params![id, agent, now],
        )?;
        if changed == 1 {
            events::record(
                &transaction,
                id,
                TaskEventKind::Released,
                Some(agent),
                now,
                "",
            )?;
        }
        transaction.commit()?;
        Ok(changed == 1)
    }
}

/// Refuse a claim that would take an agent past [`MAX_CONCURRENT_CLAIMS`]
/// (ADR-0067), naming what it already holds.
///
/// Re-claiming a task the agent already owns is never a new claim: it is the
/// heartbeat path, and refusing it would turn renewing a lease into an error at
/// exactly the wrong moment.
///
/// The refusal lists the held tasks and what to do with them. A cap that only
/// says "no" relocates the confusion rather than removing it \u2014 the holder still
/// has to go and count, which is the work this exists to stop anyone doing.
fn refuse_beyond_claim_limit(connection: &Connection, id: &str, agent: &str) -> Result<()> {
    let already_held = connection.query_row(
        "SELECT EXISTS(
             SELECT 1 FROM tasks
             WHERE id = ?1 AND status = 'claimed' AND owner = ?2
         )",
        params![id, agent],
        |row| row.get::<_, bool>(0),
    )?;
    if already_held {
        return Ok(());
    }

    let mut statement = connection.prepare(
        "SELECT id, title FROM tasks
         WHERE status = 'claimed' AND owner = ?1
         ORDER BY updated_at ASC, id ASC",
    )?;
    let held = collect(statement.query_map(params![agent], |row| {
        Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
    })?)?;
    if held.len() < MAX_CONCURRENT_CLAIMS {
        return Ok(());
    }
    let listed = held
        .iter()
        .map(|(id, title)| format!("\n  {id}  {title}"))
        .collect::<String>();
    Err(LodestarError::Invalid(format!(
        "{agent} already holds {} claims and the limit is {MAX_CONCURRENT_CLAIMS}; \
         claiming {id} as well would be a statement about work nobody is doing. \
         Complete one, release it, or leave it for another agent — a lapsed lease \
         still counts, because letting a claim go stale is not finishing it.{listed}",
        held.len(),
    )))
}

#[cfg(test)]
mod tests {
    use super::super::tests::working_on;
    use super::*;
    use crate::store::test_support::*;
    use mindleak_session::SessionContext;
    use rusqlite::params;

    fn branch_context(branch: &str) -> SessionContext {
        SessionContext {
            branch: Some(branch.to_string()),
            ..SessionContext::default()
        }
    }

    // ADR-0057. A merge can only be checked against the work it came from if
    // the ledger knows which branch that work was done on. `open_session`
    // already collects it, so claiming joins the two rather than asking anyone
    // to declare it twice.
    #[test]
    fn claiming_records_the_branch_the_session_declared() {
        let store = store();
        let goal = goal(&store);
        let task = store
            .create_task(&goal.id, "do the thing", "done", None, NOW)
            .unwrap();
        working_on(&store, "agent-a", Some("feat/the-thing"));

        assert!(store.claim_task(&task.id, "agent-a", 300, NOW).unwrap());

        assert_eq!(
            store.get_task(&task.id).unwrap().unwrap().branch.as_deref(),
            Some("feat/the-thing"),
            "the branch must be readable from a task read"
        );
    }

    // A session that declared no branch is recorded as none, not refused: the
    // server never inspects Git (ADR-0044), so the only honest alternatives are
    // NULL or a guess, and a guess would be worse than knowing nothing.
    #[test]
    fn a_session_that_declared_no_branch_still_claims() {
        let store = store();
        let goal = goal(&store);
        let task = store
            .create_task(&goal.id, "do the thing", "done", None, NOW)
            .unwrap();
        working_on(&store, "agent-a", None);

        assert!(store.claim_task(&task.id, "agent-a", 300, NOW).unwrap());
        assert_eq!(store.get_task(&task.id).unwrap().unwrap().branch, None);
    }

    // The branch belongs to the evidence window, not to the agent. Re-reading
    // it on every re-claim would let an agent that has since moved on silently
    // rename the branch its earlier commits were made on — which is the single
    // thing this column exists to pin down.
    #[test]
    fn a_same_owner_reclaim_keeps_the_branch_the_window_started_on() {
        let store = store();
        let goal = goal(&store);
        let task = store
            .create_task(&goal.id, "do the thing", "done", None, NOW)
            .unwrap();
        working_on(&store, "agent-a", Some("feat/where-the-work-happened"));
        assert!(store.claim_task(&task.id, "agent-a", 300, NOW).unwrap());

        // The same agent moves to another branch and re-claims after a lapse.
        working_on(&store, "agent-a", Some("feat/somewhere-else"));
        assert!(store
            .claim_task(&task.id, "agent-a", 300, NOW + 10_000)
            .unwrap());

        let claimed = store.get_task(&task.id).unwrap().unwrap();
        assert_eq!(
            claimed.branch.as_deref(),
            Some("feat/where-the-work-happened"),
            "a re-claim must not rewrite the branch the window's work was done on"
        );
        assert_eq!(
            claimed.claim_started_at,
            Some(NOW),
            "and it follows the same window as claim_started_at"
        );
    }

    // A different owner opens a fresh window, so the branch is re-read with it.
    #[test]
    fn a_new_owner_opens_a_fresh_window_and_rereads_the_branch() {
        let store = store();
        let goal = goal(&store);
        let task = store
            .create_task(&goal.id, "do the thing", "done", None, NOW)
            .unwrap();
        working_on(&store, "agent-a", Some("feat/first"));
        assert!(store.claim_task(&task.id, "agent-a", 300, NOW).unwrap());

        working_on(&store, "agent-b", Some("feat/second"));
        assert!(store
            .claim_task(&task.id, "agent-b", 300, NOW + 10_000)
            .unwrap());

        let claimed = store.get_task(&task.id).unwrap().unwrap();
        assert_eq!(claimed.branch.as_deref(), Some("feat/second"));
        assert_eq!(claimed.claim_started_at, Some(NOW + 10_000));
    }

    #[test]
    fn claim_is_a_compare_and_swap() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();

        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap()); // open -> alice wins
        assert!(!s.claim_task(&t.id, "bob", 60, NOW).unwrap()); // live claim -> bob loses
        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap()); // owner re-claim idempotent

        let held = s.get_task(&t.id).unwrap().unwrap();
        assert_eq!(held.owner.as_deref(), Some("alice"));
        assert_eq!(held.status, TaskStatus::Claimed);
    }

    /// Bug: nothing limited how many tasks one agent could hold, and holding a
    /// claim it was not working cost it nothing. Measured on the live board: 36
    /// tasks `claimed`, **4** with a live lease, the rest lapsed a median of 13
    /// hours earlier — two agents holding 15 and 14 apiece. Impact: the board
    /// read as a fleet with 36 things in flight when it had 4, so both humans
    /// and agents planned against a number that was nine times wrong, and
    /// discovering it took a bespoke script. Fix: refuse the claim that would
    /// take an agent past the limit, counting lapsed claims too (ADR-0067).
    #[test]
    fn an_agent_cannot_hold_more_claims_than_it_can_be_working() {
        let s = store();
        let g = goal(&s);
        let tasks: Vec<_> = (0..MAX_CONCURRENT_CLAIMS + 1)
            .map(|n| {
                s.create_task(&g.id, &format!("task {n}"), "", None, NOW + n as i64)
                    .unwrap()
            })
            .collect();
        for task in tasks.iter().take(MAX_CONCURRENT_CLAIMS) {
            assert!(s.claim_task(&task.id, "alice", 60, NOW).unwrap());
        }

        let refused = s
            .claim_task(&tasks[MAX_CONCURRENT_CLAIMS].id, "alice", 60, NOW)
            .unwrap_err()
            .to_string();
        assert!(refused.contains("already holds"), "{refused}");
        assert!(
            refused.contains(&tasks[0].id),
            "names what is already held: {refused}"
        );

        // A lapsed lease still counts: letting a claim go stale is not finishing
        // it, and if it did not count it would be the cheapest way to dodge the
        // limit — which is precisely the behaviour this exists to stop.
        let lapsed = NOW + 1_000;
        let still_refused = s
            .claim_task(&tasks[MAX_CONCURRENT_CLAIMS].id, "alice", 60, lapsed)
            .unwrap_err()
            .to_string();
        assert!(still_refused.contains("already holds"), "{still_refused}");

        // Re-claiming something already held is a heartbeat, not a new claim.
        assert!(s.claim_task(&tasks[0].id, "alice", 60, lapsed).unwrap());

        // Existing ledgers may already be over the cap. Re-claiming one of
        // those tasks still is not a new claim: refusing it would prevent the
        // holder renewing, recording the lapse, or preserving its ADR-0048
        // evidence window until it can finish/release the excess.
        let grandfathered = s
            .create_task(&g.id, "grandfathered", "", None, NOW)
            .unwrap();
        s.conn
            .execute(
                "UPDATE tasks
                 SET status = 'claimed', owner = 'alice', claim_started_at = ?2,
                     lease_expires_at = ?3, updated_at = ?2
                 WHERE id = ?1",
                params![grandfathered.id, NOW, NOW + 60],
            )
            .unwrap();
        assert!(s
            .claim_task(&grandfathered.id, "alice", 60, lapsed)
            .unwrap());
        assert!(s.release_task(&grandfathered.id, "alice", lapsed).unwrap());

        // Another agent is unaffected, and finishing one frees the slot.
        assert!(s
            .claim_task(&tasks[MAX_CONCURRENT_CLAIMS].id, "bob", 60, NOW)
            .unwrap());
        assert!(s.release_task(&tasks[1].id, "alice", NOW).unwrap());
        let freed = s.create_task(&g.id, "one more", "", None, NOW).unwrap();
        assert!(s.claim_task(&freed.id, "alice", 60, NOW).unwrap());
    }

    #[test]
    fn scoped_claim_is_atomic_and_overlap_is_advisory() {
        let store = store();
        let goal = goal(&store);
        let first = store.create_task(&goal.id, "first", "", None, NOW).unwrap();
        let second = store
            .create_task(&goal.id, "second", "", None, NOW + 1)
            .unwrap();
        let scope = TaskScope {
            paths: vec!["src/**/*.rs".into(), "src/lib.rs".into()],
            symbols: vec!["symbol:src/lib.rs:run".into()],
        };

        assert!(store
            .claim_task_with_scope(&first.id, "alice", 60, &scope, NOW + 2)
            .unwrap());
        assert!(!store
            .claim_task_with_scope(
                &first.id,
                "bob",
                60,
                &TaskScope {
                    paths: vec!["other/**".into()],
                    symbols: vec![],
                },
                NOW + 3,
            )
            .unwrap());

        let overlaps = store
            .check_claim_overlap(
                &TaskScope {
                    paths: vec!["src/lib.rs".into()],
                    symbols: vec!["symbol:src/lib.rs:run".into()],
                },
                Some(&second.id),
                None,
                NOW + 3,
            )
            .unwrap()
            .claims;
        assert_eq!(overlaps.len(), 1);
        assert_eq!(overlaps[0].task_id, first.id);
        assert_eq!(overlaps[0].owner, "alice");
        assert_eq!(overlaps[0].scope, scope);
        assert_eq!(overlaps[0].matching_paths, vec!["src/lib.rs"]);
        assert_eq!(overlaps[0].matching_symbols, vec!["symbol:src/lib.rs:run"]);

        // Read-only advisory check does not disturb the live claim.
        assert_eq!(
            store.get_task(&first.id).unwrap().unwrap().owner.as_deref(),
            Some("alice")
        );
        assert!(store
            .check_claim_overlap(&TaskScope::default(), None, None, NOW + 3)
            .unwrap()
            .claims
            .is_empty());
        assert!(store
            .check_claim_overlap(&scope, None, None, NOW + 63)
            .unwrap()
            .claims
            .is_empty());

        // Requested paths are concrete, while claim declarations are globs.
        assert!(store
            .claim_task_with_scope(
                &second.id,
                "bob",
                60,
                &TaskScope {
                    paths: vec!["special/literal.rs".into()],
                    symbols: vec![],
                },
                NOW + 3,
            )
            .unwrap());
        assert!(store
            .check_claim_overlap(
                &TaskScope {
                    paths: vec!["special/[literal].rs".into()],
                    symbols: vec![],
                },
                None,
                None,
                NOW + 3,
            )
            .unwrap()
            .claims
            .is_empty());
    }

    /// ADR-0035 heuristic 4: an intersection is not one risk. Two agents on the
    /// same declared branch collide now; on different branches they are storing
    /// up a merge. Before this the caller got the same answer for both and had
    /// to guess, which is how advisory output gets ignored.
    #[test]
    fn overlap_signal_separates_same_branch_collision_from_cross_branch_merge_risk() {
        let store = store();
        let goal = goal(&store);
        let scope = TaskScope {
            paths: vec!["src/lib.rs".into()],
            symbols: vec![],
        };
        let held = store.create_task(&goal.id, "held", "", None, NOW).unwrap();
        assert!(store
            .claim_task_with_scope(&held.id, "alice", 60, &scope, NOW)
            .unwrap());
        store
            .declare_session_context("alice", &branch_context("fleet/a"), NOW)
            .unwrap();

        // Same declared branch: the edits land in one history.
        store
            .declare_session_context("bob", &branch_context("fleet/a"), NOW)
            .unwrap();
        let report = store
            .check_claim_overlap(&scope, None, Some("bob"), NOW)
            .unwrap();
        assert_eq!(report.requester_branch.as_deref(), Some("fleet/a"));
        assert_eq!(report.claims.len(), 1);
        assert_eq!(report.claims[0].owner_branch.as_deref(), Some("fleet/a"));
        assert_eq!(report.claims[0].signal, OverlapSignal::SameBranchCollision);

        // Different declared branches: divergence, paid at merge.
        store
            .declare_session_context("bob", &branch_context("fleet/b"), NOW + 1)
            .unwrap();
        let report = store
            .check_claim_overlap(&scope, None, Some("bob"), NOW + 1)
            .unwrap();
        assert_eq!(report.requester_branch.as_deref(), Some("fleet/b"));
        assert_eq!(report.claims[0].signal, OverlapSignal::CrossBranchMergeRisk);

        // Either side silent degrades to today's behaviour, and says which side.
        let report = store.check_claim_overlap(&scope, None, None, NOW).unwrap();
        assert_eq!(report.requester_branch, None);
        assert_eq!(report.claims[0].owner_branch.as_deref(), Some("fleet/a"));
        assert_eq!(report.claims[0].signal, OverlapSignal::Undeclared);

        let unregistered = store
            .check_claim_overlap(&scope, None, Some("nobody"), NOW)
            .unwrap();
        assert_eq!(unregistered.claims[0].signal, OverlapSignal::Undeclared);

        // A session that registered without declaring a branch is silent too:
        // an empty declaration is not a branch nobody else is on.
        store
            .declare_session_context("bob", &SessionContext::default(), NOW + 2)
            .unwrap();
        let report = store
            .check_claim_overlap(&scope, None, Some("bob"), NOW + 2)
            .unwrap();
        assert_eq!(report.requester_branch, None);
        assert_eq!(report.claims[0].signal, OverlapSignal::Undeclared);

        // Still advisory: nothing about the classification blocks a claim.
        assert!(store
            .claim_task_with_scope(
                &store
                    .create_task(&goal.id, "rival", "", None, NOW + 2)
                    .unwrap()
                    .id,
                "bob",
                60,
                &scope,
                NOW + 2
            )
            .unwrap());
    }

    #[test]
    fn scoped_claim_rejects_invalid_globs_before_claiming() {
        let store = store();
        let goal = goal(&store);
        let task = store.create_task(&goal.id, "task", "", None, NOW).unwrap();
        let error = store
            .claim_task_with_scope(
                &task.id,
                "alice",
                60,
                &TaskScope {
                    paths: vec!["src/[".into()],
                    symbols: vec![],
                },
                NOW + 1,
            )
            .unwrap_err();
        assert!(error.to_string().contains("invalid task scope glob"));
        assert_eq!(
            store.get_task(&task.id).unwrap().unwrap().status,
            TaskStatus::Open
        );
    }

    #[test]
    fn expired_lease_is_reclaimable_by_another_agent() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();

        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap());
        // 2 hours later, alice's 60s lease has long expired.
        let later = NOW + 2 * HOUR;
        assert!(s.claim_task(&t.id, "bob", 60, later).unwrap());
        assert_eq!(
            s.get_task(&t.id).unwrap().unwrap().owner.as_deref(),
            Some("bob")
        );
    }

    // ADR-0052. Observed repeatedly in one session: a claim taken with a 3600s
    // lease lapsed during `cargo test --all`, and the push that followed was
    // refused for having no live claim. The agent was working the whole time.
    #[test]
    fn activity_extends_the_lease_of_the_owner() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();
        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap());
        let before = s.get_task(&t.id).unwrap().unwrap();

        // 30s in, still inside the lease: a call naming the task is proof of life.
        assert!(s.touch_lease(&t.id, "alice", 300, NOW + 30).unwrap());

        let after = s.get_task(&t.id).unwrap().unwrap();
        assert_eq!(after.lease_expires_at, Some(NOW + 30 + 300));
        assert!(after.lease_expires_at > before.lease_expires_at);
        // ADR-0048 is unaffected: the window still starts where the claim did.
        assert_eq!(after.claim_started_at, before.claim_started_at);
    }

    // A heartbeat may only extend. An owner who deliberately took a long lease
    // must not have it cut short by a passing read.
    #[test]
    fn activity_never_shortens_a_longer_lease() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();
        assert!(s.claim_task(&t.id, "alice", 4 * HOUR, NOW).unwrap());

        assert!(s.touch_lease(&t.id, "alice", 300, NOW + 30).unwrap());

        assert_eq!(
            s.get_task(&t.id).unwrap().unwrap().lease_expires_at,
            Some(NOW + 4 * HOUR)
        );
    }

    // Owner-only and silent. A peer reading the task renews nothing, and a
    // lapsed lease is not resurrected by a passing call — it still requires a
    // deliberate re-claim, or the claim someone else took could be undone.
    #[test]
    fn activity_by_a_non_owner_or_after_a_lapse_renews_nothing() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();
        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap());

        assert!(!s.touch_lease(&t.id, "bob", 300, NOW + 30).unwrap());
        assert!(!s.touch_lease(&t.id, "alice", 300, NOW + 2 * HOUR).unwrap());

        assert_eq!(
            s.get_task(&t.id).unwrap().unwrap().lease_expires_at,
            Some(NOW + 60)
        );
    }

    // Bug (ADR-0048): a lapsed lease used to silently shrink the evidence
    // window. Re-claiming reset `claim_started_at` to the moment of the
    // re-claim, so every commit made before the lapse fell outside the window
    // the agent was allowed to prove — and because the verdict is computed over
    // whatever the evidence covers, the agent could submit the surviving sliver
    // and collect an `aligned` receipt while the bulk of the work went
    // unchecked. The fix keeps the window open across a lapse by the same owner
    // and counts the hole instead, so the work stays provable and the
    // discontinuity is on the record for conformance to act on.
    #[test]
    fn a_lapsed_lease_keeps_the_evidence_window_and_counts_the_hole() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();

        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap());
        assert!(s.renew_lease(&t.id, "alice", 60, NOW + 30).unwrap());
        let live = s.get_task(&t.id).unwrap().unwrap();
        assert_eq!(live.claim_started_at, Some(NOW));
        // A renewed, unbroken window has nothing to declare.
        let clean = s.claim_window(&t.id).unwrap();
        assert_eq!(clean.lapses, 0);
        assert_eq!(clean.unleased_seconds, 0);

        // The lease lapses at NOW + 90 and alice does not return for 2 hours.
        let after_expiry = NOW + 2 * HOUR;
        assert!(!s.renew_lease(&t.id, "alice", 60, after_expiry).unwrap());
        assert!(s.claim_task(&t.id, "alice", 60, after_expiry).unwrap());

        let reclaimed = s.get_task(&t.id).unwrap().unwrap();
        // The window still reaches back to the original claim, so work done
        // before the lapse remains provable.
        assert_eq!(reclaimed.claim_started_at, Some(NOW));
        assert_eq!(reclaimed.lease_expires_at, Some(after_expiry + 60));
        // ...and the hole it now contains is recorded rather than forgotten.
        let holed = s.claim_window(&t.id).unwrap();
        assert_eq!(holed.lapses, 1);
        assert_eq!(holed.unleased_seconds, after_expiry - (NOW + 90));
    }

    #[test]
    fn a_second_lapse_accumulates_and_a_new_owner_starts_clean() {
        let s = store();
        let g = goal(&s);
        let t = s.create_task(&g.id, "task", "", None, NOW).unwrap();

        assert!(s.claim_task(&t.id, "alice", 60, NOW).unwrap());
        let first = NOW + HOUR;
        assert!(s.claim_task(&t.id, "alice", 60, first).unwrap());
        let second = NOW + 2 * HOUR;
        assert!(s.claim_task(&t.id, "alice", 60, second).unwrap());

        let twice_lapsed = s.get_task(&t.id).unwrap().unwrap();
        assert_eq!(twice_lapsed.claim_started_at, Some(NOW));
        let window = s.claim_window(&t.id).unwrap();
        assert_eq!(window.lapses, 2);
        assert_eq!(
            window.unleased_seconds,
            (first - (NOW + 60)) + (second - (first + 60))
        );

        // A different owner inherits none of it: the window is theirs alone, so
        // it starts now, continuous, and carries no one else's holes.
        let third = NOW + 3 * HOUR;
        assert!(s.claim_task(&t.id, "bob", 60, third).unwrap());
        let bob = s.get_task(&t.id).unwrap().unwrap();
        assert_eq!(bob.claim_started_at, Some(third));
        let bob_window = s.claim_window(&t.id).unwrap();
        assert_eq!(bob_window.lapses, 0);
        assert_eq!(bob_window.unleased_seconds, 0);
    }
}
